def _parse_data(self):
    """
    Parse security requirement data.
    Empty dict means no security required.
    Non-empty dict has one key (security scheme name) with list of scopes.
    """
    if len(self.raw_element.keys()) == 0:
        # Empty security requirement - no security required
        self.name = None
        self.types = []
    else:
        # Regular security requirement with one key
        self.name  = [c for c in self.raw_element.keys()][0]
        self.types = self._get(self.name, str, is_list=True)

@classmethod
def can_parse(cls, dct):
    """
    This needs to ignore can_parse since the objects it's parsing are not
    regular - they must always have only one key though or be empty.
    """
    # Empty dict means no security required - this is valid
    if len(dct.keys()) == 0:
        return True
    # Regular security requirement with one key whose value is a list
    return len(dct.keys()) == 1 and isinstance([c for c in dct.values()][0], list)

def __getstate__(self):
    if self.name is None:
        # Empty security requirement
        return {}
    return {self.name: self.types}
